create table if not exists public.profitability_recommendations (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, venue_id uuid not null references public.venues(id) on delete cascade, kind text not null, title text not null, detail text not null, period_from timestamptz not null, period_to timestamptz not null, source jsonb not null default '{}'::jsonb, status text not null default 'pending' check (status in ('pending','accepted','ignored','snoozed')), decided_by uuid references auth.users(id), decided_at timestamptz, created_at timestamptz not null default now());
create index if not exists profitability_recommendations_window_idx on public.profitability_recommendations(tenant_id, venue_id, created_at desc);
alter table public.profitability_recommendations enable row level security; alter table public.profitability_recommendations force row level security;
create policy profitability_recommendations_read on public.profitability_recommendations for select using (public.is_tenant_member(tenant_id)); create policy profitability_recommendations_write on public.profitability_recommendations for all using (public.has_tenant_role(tenant_id, array['owner','manager']::public.tenant_role[])) with check (public.has_tenant_role(tenant_id, array['owner','manager']::public.tenant_role[]));
